            "import * as React from 'react';\n\
             interface DialogContentProps { forceMount?: true; onEscapeKeyDown?: (event: KeyboardEvent) => void }\n\
             declare const DialogContent: React.ForwardRefExoticComponent<DialogContentProps>;\n\
